	private static final Logger LOGGER = Logger.getLogger(DeskIntegration.class.getName());

	private static final String APIURL = CommonUtil.getProperty("desk") + "/api/v1/";
	private static final String SINGLEATTACHMENTDETAILS = "select BlockID,FilePath from FeedbackAttachment where AttachmentID=?;";

	public static final String DESK_TICKET_UPDATE_EVENT = "Ticket_Update";
	public static final String DESK_TICKET_COMMENT_ADD_EVENT = "Ticket_Comment_Add";
	public static final String DESK_TICKET_COMMENT_UPDATE_EVENT = "Ticket_Comment_Update";

	private JSONObject getIntegDetail(String moduleName, String subType, Long apID)
	{
		return IntegrationHandler.getIntegrationDetails(AppticsConstants.NEWDESKINTEGRATION, moduleName, subType, apID);
	}

	private String getUserAccessToken(long zuid)
	{
		String clientID = CommonUtil.getPropertyFromDB(true, AppticsConstants.DESKCLIENTID);
		String[] scope = {"Desk.tickets.ALL", "Desk.contacts.READ", "Desk.contacts.WRITE", "Desk.contacts.UPDATE", "Desk.contacts.CREATE", "Desk.tasks.ALL", "Desk.basic.READ", "Desk.basic.CREATE", "Desk.search.READ", "Desk.settings.ALL", "Desk.events.ALL"};
		return AppticsIAMOAuthHandler.getAccessToken(AppticsConstants.DESK, clientID, zuid, null, scope);
	}

	private JSONObject getIntegrationDetails(String moduleName, String subType, Long apID)
	{
		JSONObject configuration = getIntegDetail(moduleName, subType, apID);

		if (CommonUtil.isEmpty(configuration))
		{
			LOGGER.log(Level.INFO, "Getting configuration as empty.");
			return null;
		}

		try
		{
			Long zuid = configuration.getLong("zuid");
			if (CommonUtil.isEmpty(zuid))
			{
				LOGGER.log(Level.INFO, "Getting zuid as empty.");
				return null;
			}

			String accessToken = getUserAccessToken(zuid);

			if (CommonUtil.isEmpty(accessToken))
			{
				LOGGER.log(Level.INFO, "Getting access token as empty.");
				return null;
			}

			JSONObject deskDetails = new JSONObject();
			deskDetails.put("orgID", configuration.getLong("orgid"));
			deskDetails.put("depID", configuration.getString("departmentid"));
			deskDetails.put("guestcontactid", configuration.has("guestcontactid") ? configuration.getString("guestcontactid") : "");
			deskDetails.put("accessToken", accessToken);
			deskDetails.put("orgName", configuration.has("orgname") ? configuration.getString("orgname") : "");
			deskDetails.put("departmentName", configuration.has("departmentname") ? configuration.getString("departmentname") : "");
			deskDetails.put("zuid", zuid);

			return deskDetails;

		}
		catch (JSONException e)
		{
			LOGGER.log(Level.SEVERE, "Exception while get cliq integration.", e);
		}
		return null;
	}


	protected String checkAndGetGuestContactID(long apID, long orgID, long zuid)
	{
		String accessToken = getUserAccessToken(zuid);
		String guestusername = "GuestUser";
		try
		{
			Long projectID = AppHandler.getInstance().getProjectID(apID);
			String displayName = ProjectHandler.getDisplayName(projectID);
			guestusername = displayName + guestusername;
		}
		catch(DataAccessException e)
		{
			LOGGER.log(Level.SEVERE, "", e);
		}
		return checkAndCreateContact(orgID, accessToken, guestusername, null, true);
	}

	private String checkAndCreateContact(long orgID, String accessToken, String newName, String email, boolean isGuestUser)
    {

        String searchURL = APIURL+"contacts/search";
        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", accessToken);
        headers.put("orgId", orgID+"");

        Map<String, String> params = new HashMap<>();
//        params.put("limit", "1");
        params.put("lastName", newName);
        params.put("email", email);

        try 
        {
            String res = new HttpURLConnectionInvoker(false).invokeGetHttpURLConn(searchURL, headers, params);
            LOGGER.info("Search Contacts response " + res);
            if(res.contains("{")){
                JSONObject resJSON = new JSONObject(res);
                if(resJSON.has("data"))
                {
                    JSONArray contacts = resJSON.getJSONArray("data");
                    for(int i = 0; i < contacts.length() ; i++)
                    {
                        JSONObject contact = contacts.getJSONObject(i);
                        if(isGuestUser)
                        {
                        	String existname = contact.getString("lastName");
                        	if(newName.equals(existname))
                        	{
                        		LOGGER.info("Lastname matched in this >> " + contact.toString());
                        		return contact.getString("id");
                        	}
                        }
                        else
                        {
	                        String existemail = contact.has("email") ? contact.getString("email") : "";
	                        if(existemail.equalsIgnoreCase(email))
	                        {
	                            LOGGER.info("Lastname matched in this >> " + contact.toString());
	                            return contact.getString("id");
	                        }
                        }
                    }
                }
            }

            JSONObject params1 = new JSONObject();
            params1.put("lastName", newName);
            if(!CommonUtil.isEmpty(email))
            {
                params1.put("email", email);
            }
            String createContactURL = APIURL+"contacts";
            JSONObject newcontactres = new HttpURLConnectionInvoker(false).invokeHttpURLConn(1, createContactURL, headers, params1, null, false );
            LOGGER.info("New Contacts response " + newcontactres.toString());
            if(newcontactres.has("id"))
            {
                JSONObject newcontactnew = newcontactres.getJSONObject("response");
                return newcontactnew.getString("id");
            }

        }
        catch (Exception e) 
        {
            LOGGER.log(Level.SEVERE, "Exception while search and create contact id ", e);
        }
        return "";
    }

	public Map<String, Object> createTicket(long projectID, long feedID)
	{
		return createTicket(projectID, feedID, null);

	}

	public Map<String, Object> createTicket(long projectID, long feedID, Map<String, Object> feedInfo)
	{
		if(CommonUtil.isEmpty(feedInfo))
		{
			feedInfo = getFeedInfo(projectID, feedID);
			LOGGER.info("Feedinfo from DB"+ feedInfo.toString());
		}

		Long osVersionID = (Long)feedInfo.get(AppticsConstants.OSVERSIONID);

		osVersionID = CommonUtil.isEmpty(osVersionID) ? getOSVersionIDByFeedID(feedID) : osVersionID;
		feedInfo.put(AppticsConstants.OSVERSIONID, osVersionID);

		try 
		{
			feedInfo.put(AppticsConstants.OSVERSION, OSVersionHandler.getInstance().getVersionNameByVersionID(osVersionID));
		}
		catch(DataAccessException e)
		{
			LOGGER.log(Level.SEVERE, "Exception getting os verion", e);
			feedInfo.put(AppticsConstants.OSVERSION, "");
		}

		feedInfo.put("DeskWebURL", null);

		LOGGER.info("Feed info "+ feedInfo.toString());

		String email = (String)feedInfo.get("MailID");
		long appID = (long)feedInfo.get("AppID");
		long date = (long)feedInfo.get("Date");
		String report = (String)feedInfo.get("Report");
		int type = (int)feedInfo.get("Type");
		int mode = (int)feedInfo.get("Mode");
		long pid = (long)feedInfo.get("PID");
		long apID = (long)feedInfo.get("BundleID");
		String appversion = (String)feedInfo.get("AppVersion");

		LOGGER.info("APID : " + apID);

		String moduleName = getModuleName(type) ;

		String projectDisplayname = "";
		try 
		{
			projectDisplayname = ProjectHandler.getDisplayName(appID);
		}
		catch(DataAccessException e)
		{
			LOGGER.log(Level.SEVERE, "Exception while ", e);
		}

		feedInfo.put("projectDisplayname", projectDisplayname);

		report = CommonUtil.isEmpty(report) ? "new "+moduleName+" received" : report ;

		JSONObject deskDetails = getIntegrationDetails("feedback", moduleName, apID);

		if(CommonUtil.isEmpty(deskDetails))
		{
			LOGGER.log(Level.INFO, "Getting desk configuration as empty for {0}", new Object[] { apID });
			return feedInfo;
		}
		//for mail send
		String timezone = AdminDBCache.getInstance().getTimeZone(appID);
		long startDateTimestamp = CalendarUtil.getStartTimeByLongDate(date, timezone);
		long endDateTimestamp = CalendarUtil.getEndTimeByLongDate(date, timezone);
		String startDate = CalendarUtil.formatDate("yyyy-MM-dd", startDateTimestamp, timezone);
		String endDate = CalendarUtil.formatDate("yyyy-MM-dd", endDateTimestamp, timezone);
		String zsoid = CommonUtil.getSASThreadLocalLoginName();
		String reporturl = AppticsConstants.SERVICEURL+"/ac/"+zsoid+"/"+appID+"/"+mode+"/tickets/11?sD="+startDate+"&eD="+endDate+"&feedID="+feedID;

        try
        {
        	long orgID = deskDetails.getLong("orgID");
        	String departmentID = deskDetails.getString("depID");
        	String accessToken = deskDetails.getString("accessToken");
        	String lastName = projectDisplayname+"GuestUser";
			JSONObject contact = new JSONObject();

        	if(!CommonUtil.isEmpty(email) && CommonUtil.isValidEmail(email))
        	{
				String[] parts = email.split("@");
				lastName = parts[0];
				if(lastName.length() < 3) 
				{
					lastName = parts[1].split("\\.")[0] + "-" + lastName ;
				}
				contact.put("email", email);
        	}

			LOGGER.info("orgid == > " + orgID + "department id === > " + departmentID);

			String url = APIURL+"tickets";

			Map<String, String> headers = new HashMap<>();
			headers.put("Authorization", accessToken);
			headers.put("orgId", orgID+"");

			String modestr = mode == 1 ? "" : " - Development";
			String subject = moduleName+" - " + projectDisplayname + " " + appversion + " - " + AdminDBCache.getInstance().getOS(pid) + " " + feedInfo.get("OSVersion") + modestr;
			contact.put("lastName", lastName);

			JSONObject params = new JSONObject();
			params.put("subject", subject);
//			params.put("contactId", contactID);
			params.put("departmentId", departmentID);
			params.put("description", report);
			params.put("channel", "Email");
			params.put("contact", contact);

            JSONObject res = new HttpURLConnectionInvoker(false).invokeHttpURLConn(1, url, headers, params, null, false);

//			JSONObject ticketDetails = res.getJSONObject("response");

			if(res.has("id"))
			{
				String ticketID = res.getString("id");

				String webURL = res.getString("webUrl");
				Criteria c = new Criteria(Column.getColumn(AppticsConstants.BUGREPORTDETAILS, AppticsConstants.FEEDID), feedID, QueryConstants.EQUAL);

				JSONObject desk = new JSONObject();
				desk.put(AppticsConstants.FEEDID, feedID);
				desk.put(AppticsConstants.TICKETID, ticketID);
				desk.put(AppticsConstants.ORGNAME, deskDetails.getString("orgName"));
				desk.put(AppticsConstants.ORGID, orgID);
				desk.put(AppticsConstants.DEPARTMENTID, departmentID);
				desk.put(AppticsConstants.C_ZUID, deskDetails.get("zuid"));
				desk.put(AppticsConstants.DEPARTMENTNAME, deskDetails.getString("departmentName"));
				desk.put(AppticsConstants.ASSIGNEE, "Not Assigned");
				desk.put(AppticsConstants.ASSIGNEEID, "");
				desk.put(AppticsConstants.WEBURL, webURL);
				desk.put(AppticsConstants.DATE, System.currentTimeMillis());
				desk.put(AppticsConstants.STATUSTEXT, res.getString("status"));
				desk.put(AppticsConstants.TICKETNUMBER, res.getLong("ticketNumber"));
				desk.put(AppticsConstants.CLASSIFICATION, "");
				desk.put(AppticsConstants.THREADS, "");
				desk.put(AppticsConstants.STATUS, "");
				desk.put(AppticsConstants.PRIORITY, "");

				JSONObject integDetails = IntegrationHandler.getIntegrationDetails(feedID);
				integDetails.put("Desk", desk);
				DBHandler.update(AppticsConstants.BUGREPORTDETAILS, c, AppticsConstants.INTEGRATIONDETAILS, integDetails.toString());

				checkAndUploadAttachment(appID, ticketID, orgID, feedID, accessToken);
				String ProjectIDs = PropertyHandler.getValue("DeskDefaultComment");
				if(!CommonUtil.isEmpty(ProjectIDs) && ProjectIDs.contains(appID+""))
				{
					String comment = AdminDBCache.getInstance().getOS(pid)+" - "+feedInfo.get(AppticsConstants.OSVERSION)+" - Appversion : "+appversion+" - "+feedInfo.get(AppticsConstants.MODEL)
					+" - "+"<a href='"+reporturl+"' target='_blank'>View in Apptics</a>";
					addCommentByToken(orgID, ticketID, comment, accessToken);
				}
				feedInfo.put("DeskWebURL", webURL);
			}
			else
			{
				feedInfo.put("ZDeskErrorMessage", res.has("Message") ? res.get("Message") : "Error while creating the desk ticket");
				LOGGER.log(Level.INFO, res.toString());
			}
		}
    	catch(Exception e)
    	{
		LOGGER.log(Level.SEVERE,"Exception while creating desk ticket",e);
    	}

		return feedInfo;
	};

	private void checkAndUploadAttachment(long appID, String ticketID, long orgID, long feedID, String accessToken)
	{
		LOGGER.info("Coming checkAndUploadAttachment for FeedID == " + feedID);
		SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.FEEDBACKATTACHMENT));
		sq.addSelectColumn(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.ATTACHMENTID));
		sq.addSelectColumn(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.FILEPATH));
		sq.addSelectColumn(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.BLOCKID));
		sq.setCriteria(new Criteria(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.FEEDID),feedID, QueryConstants.EQUAL));

		DataObject dobj = null;
		File file = null;
		try 
		{
			dobj = DBHandler.getPersistence().get(sq);
			if (!dobj.containsTable(AppticsConstants.FEEDBACKATTACHMENT))
			{
				LOGGER.info("No Rows found match with feedid = " + feedID);
			}
			else
			{
				@SuppressWarnings("unchecked")
				Iterator<Row> rows = dobj.getRows(AppticsConstants.FEEDBACKATTACHMENT);
				while(rows.hasNext())
				{
					Row row = rows.next();
					String filePath = (String)row.get(AppticsConstants.FILEPATH);
					String blockID = (String)row.get(AppticsConstants.BLOCKID);
					LOGGER.info("filePath == > "+filePath+" blockID == > "+blockID);
					file = DFSFileHandler.dfsFileReadReturnFile(filePath, blockID, appID);
					uploadFileToDesk(orgID, ticketID, file, accessToken);
				}
			}
		} 
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE,"Exception while getting access token to add desk ticket", e);
		}
		finally
		{
			CommonUtil.deleteTmpFileInAppServer(file);
		}
	}

