	public void checkTicketAndUploadAttachment(long appID, long attachmentID, long feedID)
	{

		Map<String, Object> attachmentDetails = DBHandler.getCommonBean().getRowAsMap(SINGLEATTACHMENTDETAILS, AppticsConstants.ATTACHMENTID, attachmentID);

		if(CommonUtil.isEmpty(attachmentDetails))
		{
			LOGGER.log(Level.INFO, "Attachment details not found.");
			return;
		}
		File file = null;
		try {
			JSONObject TicketDetails = IntegrationHandler.getIntegrationDetailsByService(AppticsConstants.DESK, feedID);

			if(CommonUtil.isEmpty(TicketDetails))
			{
				LOGGER.log(Level.INFO, "Ticket details getting as empty.");
				return;
			}


			String ticketID = TicketDetails.optString("TicketID");
			String filePath = (String) attachmentDetails.get("FilePath");
			String blockID = (String) attachmentDetails.get("BlockID");
			Long zuid = TicketDetails.getLong("ZUID");
			Long orgID =  TicketDetails.getLong("OrgID");
			String accessToken = getUserAccessToken(zuid);

			if(!CommonUtil.isEmpty(ticketID, zuid, accessToken) && !filePath.contains(".txt"))
			{
				file = DFSFileHandler.dfsFileReadReturnFile(filePath, blockID, appID);
				uploadFileToDesk(orgID, ticketID, file, accessToken);
			}
		}
		catch(JSONException e){
			LOGGER.log(Level.SEVERE, "exception while parsing json",e);
		}

		catch (DataAccessException e) {

			LOGGER.log(Level.SEVERE, "accessToken is unavailable");

		}
		finally
		{
			CommonUtil.deleteTmpFileInAppServer(file);
		}

	}

	private void addCommentByToken(long orgID, String ticketid, String comment, String accessToken)
	{
		String url = APIURL+"tickets/"+ticketid+"/comments";
		Map<String, String> headers = new HashMap<>();
		headers.put("orgId", orgID+"");
		headers.put("Authorization", accessToken);

		try {
			JSONObject commentJSON = new JSONObject();
			commentJSON.put("isPublic", "false");
			commentJSON.put("attachmentIds", new JSONArray());
			commentJSON.put("content", comment);
            JSONObject commentRes = new HttpURLConnectionInvoker(false).invokeHttpURLConn(1, url, headers, commentJSON, null, false);

			return;
		}
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while add comment ", e);
		}
	}
	private String getModuleName(int type)
	{
		if(type == 1)
		{
			return AppticsConstants.FEEDBACK;
		}
		if(type == 0)
		{
			return AppticsConstants.BUG;
		}
		if(type == 2)
		{
			return AppticsConstants.HELP;
		}
		return AppticsConstants.REPORT;
	}

    public Map<String, Object> createDeskTicket(String moduleName, String subType, Long apid, String subject, String description, String email) {

		LOGGER.log(Level.INFO, "creating ticket in zoho Desk");

		JSONObject deskDetails = IntegrationHandler.getIntegrationDetails(AppticsConstants.NEWDESKINTEGRATION, moduleName, subType, apid); //NO I18N

		if (CommonUtil.isEmpty(deskDetails))
		{
			LOGGER.log(Level.INFO, "Getting desk details as empty.");
			return null;
		}
		try
		{
			long zuid = deskDetails.getLong("zuid"); //NO I18N
			long departmentID = deskDetails.getLong("departmentid"); //NO I18N
			long orgID = deskDetails.getLong("orgid"); //NO I18N
			String clientID = CommonUtil.getPropertyFromDB(true, AppticsConstants.DESKCLIENTID);
			String[] scope = {"Desk.tickets.ALL", "Desk.contacts.READ", "Desk.contacts.WRITE", "Desk.contacts.UPDATE", "Desk.contacts.CREATE", "Desk.tasks.ALL", "Desk.basic.READ", "Desk.basic.CREATE", "Desk.search.READ", "Desk.settings.ALL", "Desk.events.ALL"};
			String accessToken = AppticsIAMOAuthHandler.getAccessToken(AppticsConstants.DESK, clientID, zuid, null, scope);
			String url = APIURL+"tickets"; //NO I18N

			Map<String, String> headers = new HashMap<>();
			headers.put("Authorization", accessToken);
			headers.put("orgId", String.valueOf(orgID));

			JSONObject params = new JSONObject();
			params.put("subject", subject);
			params.put("description", description);
			params.put("departmentId", departmentID);

			JSONObject contact = new JSONObject();
			contact.put("email", email);

			params.put("contact", contact);

	        JSONObject res = new HttpURLConnectionInvoker(false).invokeHttpURLConn(POST, url, headers, params, null, false);

			if(res.has("id"))
			{
				Map<String, Object> response = new HashMap<String, Object>();
			    response.put("response",res);
			    return response;
			}
		}
		catch(Exception e)
		{
			LOGGER.log(Level.INFO, "Exception occured while createDeskTicket", e);
		}

		return null ;
	}

	public JSONObject createDeskTicketForAaid(Long aaid, JSONObject deskDetails, String subject, String description, String lastName, String email, boolean useIAMUserTicket, Map<String, String> currentTicketHeaders) {
		return createDeskTicketForAaid(aaid, deskDetails, subject, description, lastName, email, useIAMUserTicket, currentTicketHeaders, Boolean.TRUE);
	}

    private JSONObject createDeskTicketForAaid(Long aaid, JSONObject deskDetails, String subject, String description, String lastName, String email, boolean useIAMUserTicket, Map<String, String> currentTicketHeaders, boolean retry) {

		LOGGER.info(aaid + " - Creating ZohoDeskTicket for StoreReview:\n\nSubject: " + subject + "\n\nDescription: " + description + "\n\ndeskDetails: " + deskDetails);

    	if (CommonUtil.isEmpty(deskDetails)) {
    		LOGGER.info(aaid + " - Getting desk details as empty.");
    		return null;
    	}
    	try {
    		long zuid = deskDetails.getLong("zuid"); //NO I18N
    		long departmentID = deskDetails.getLong("departmentid"); //NO I18N
    		long orgID = deskDetails.getLong("orgid"); //NO I18N

    		String url = APIURL + "tickets"; //NO I18N
    		Map<String, String> headers = new HashMap<>();

			addAuthorizationToken(headers, zuid, useIAMUserTicket, currentTicketHeaders);
    		headers.put("orgId", String.valueOf(orgID));
