	private boolean updateDepartmentIdToSubscriptions(JSONObject subscriptions, String type, long departmentID, boolean enable) {
		String requiredDeptID = String.valueOf(departmentID);
		Object webhookEventJson = subscriptions.has(type) ? subscriptions.get(type) : null;
		boolean webhookEventJsonValid = webhookEventJson != null && webhookEventJson != JSONObject.NULL && ((JSONObject) webhookEventJson).has("departmentIds");
		JSONArray departmentIds = webhookEventJsonValid ? ((JSONObject) webhookEventJson).getJSONArray("departmentIds") : new JSONArray();

		boolean existsAlready = false;
		for (int i = 0; i < departmentIds.length(); i++) {
			String deptID = departmentIds.getString(i);
			existsAlready = deptID.equals(requiredDeptID);
			if (existsAlready) {
				if (enable) {
					LOGGER.severe(type + " - updateDepartmentIdToSubscriptions - DeptID already exists in subscription: " + deptID);
				} else {
					Object removed = departmentIds.remove(i);
					LOGGER.severe(type + " - updateDepartmentIdToSubscriptions - DeptID (" + departmentID + ") exists and removed in subscription: " + removed);
				}
				break;
			}
		}
		if (!existsAlready && enable) {
			departmentIds.put(requiredDeptID);
		}
		if (!webhookEventJsonValid) {
			subscriptions.put(type, new JSONObject().put("departmentIds", departmentIds));
		}
		return !departmentIds.isEmpty();
	}

