	private boolean isRetriableDeskErrorCode(JSONObject response) {
		String errorCode = response != null && response.has("errorCode") ? response.getString("errorCode") : null;
        return errorCode != null && (errorCode.equals(UNPROCESSABLE_ENTITY) || errorCode.equals(FORBIDDEN) || errorCode.equals(BAD_REQUEST));
    }

	private static void addAuthorizationToken(Map<String, String> headers, Long zuid, boolean useIAMUserTicket, Map<String, String> currentTicketHeaders) {
		if (useIAMUserTicket && Boolean.TRUE.toString().equalsIgnoreCase(CommonUtil.getPropertyFromCommonDB("StoreReviews_Desk_UseIAMUserTicket"))) {
			if (currentTicketHeaders != null && !currentTicketHeaders.isEmpty()) {
				headers.putAll(currentTicketHeaders);
			}
			headers.put("Authorization", "Zoho-ticket " + IAMUtil.getCurrentTicket());
		} else {
			String clientID = CommonUtil.getPropertyFromDB(true, AppticsConstants.DESKCLIENTID);
			String[] scope = {"Desk.tickets.ALL", "Desk.contacts.READ", "Desk.contacts.WRITE", "Desk.contacts.UPDATE", "Desk.contacts.CREATE", "Desk.tasks.ALL", "Desk.basic.READ", "Desk.basic.CREATE", "Desk.search.READ", "Desk.settings.ALL", "Desk.events.ALL"};
			String accessToken = AppticsIAMOAuthHandler.getAccessToken(DESK, clientID, zuid, null, scope);
			headers.put("Authorization", accessToken);
		}
	}

	private static void addIgnoreSourceIdToHeader(Map<String, String> headers, JSONObject deskDetails) {
		if (deskDetails.has(DESK_WEBHOOK_ID)) {
			try {
				final long orgID = deskDetails.getLong("orgid"); //NO I18N
				final String deskWebhookId = deskDetails.getString(DESK_WEBHOOK_ID);
				final String deskWebhookCacheKey = DESK_WEBHOOK + UNDERSCORE + orgID + UNDERSCORE + deskWebhookId;
				final String deskWebhookJson = AppticsCacheHandler.getValue(deskWebhookCacheKey);
				final String ignoreSourceId = new JSONObject(deskWebhookJson).getJSONObject("webhook").getString("ignoreSourceId");

				headers.put("sourceId", ignoreSourceId);
				LOGGER.info("deskWebhookCacheKey: " + deskWebhookCacheKey + ", deskWebhookJson: " + deskWebhookJson + ", ignoreSourceId: " + ignoreSourceId);
			} catch (Exception e) {
				LOGGER.log(Level.SEVERE, "Rethrowing Exception in addIgnoreSourceIdToHeader :: ", e);
				throw e;
			}
		} else {
			LOGGER.severe("addIgnoreSourceIdToHeader skipped since desk_webhook_id is not configured: " + deskDetails);
		}
    }

