		public void createTicketInBulk(Long projectID, Long startDate, Long endDate)
    	{
			String tableName = "BugReportDetails";
			try
			{
				SelectQuery sq = new SelectQueryImpl(new Table(tableName));
				sq.addSelectColumn(Column.getColumn(tableName, "FeedID"));
				Criteria crit = new Criteria(Column.getColumn(tableName, "AppID"), projectID, QueryConstants.EQUAL);
				if(!CommonUtil.isEmpty(startDate, endDate))
				{
					crit = crit.and(new Criteria(Column.getColumn(tableName, "Date"), startDate, QueryConstants.GREATER_EQUAL));
					crit = crit.and(new Criteria(Column.getColumn(tableName, "Date"), endDate, QueryConstants.LESS_EQUAL));
				}
				sq.setCriteria(crit);
				DataObject dobj = DBHandler.getPersistence().get(sq);
				if (!dobj.containsTable(tableName))
				{
					return;
				}
				Iterator<Row> rows = dobj.getRows(tableName);
				while (rows.hasNext())
				{
					Row row = rows.next();
					Long feedID = (Long) row.get("FeedID");
		    		createTicket(projectID, feedID, null);
				}
			}
			catch (Exception e)
			{
				LOGGER.log(Level.SEVERE,"Exception while creating ticket for the date range ",e);
			}
		}

