//$Id$
package com.zoho.apptics.actions;

import java.util.Map;
import java.io.IOException;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;

import org.json.JSONArray;
import org.json.JSONObject;

import com.adventnet.iam.User;
import com.zoho.apptics.business.ServiceOrgHandler;
import com.zoho.apptics.common.EmailNotificationContent;
import com.zoho.apptics.conf.AppHandler;
import com.zoho.apptics.conf.ProjectHandler;
import com.zoho.apptics.conf.ProjectSettingsHandler;
import com.zoho.apptics.conf.RoleHandler;
import com.zoho.apptics.conf.UserHandler;
import com.zoho.apptics.integration.ZenDeskHandler;
import com.zoho.apptics.util.ApplicationLog;
import com.zoho.apptics.util.AppticsConstants;
import com.zoho.apptics.util.AppticsException;
import com.zoho.apptics.util.AppticsIAMUtil;
import com.zoho.apptics.util.ClientWriter;
import com.zoho.apptics.util.CommonUtil;
import com.zoho.apptics.util.PropertyHandler;
import com.zoho.apptics.util.TransmailNotificationUtil;


public class ZenDeskAction extends CommonAction {

	private static final long serialVersionUID = 1L;

	private static final Logger LOGGER = Logger.getLogger(ZenDeskAction.class.getName());

	private String code;
	private String state;
	private String error;

	private Long projectID;
	private Long apid;

	private boolean status = true;

	private String comment;
	private Long feedID;

	private String updateKey;
	private String updateValue;


	public void authenticate() 
	{
		LOGGER.log(Level.INFO, "authenciating zendesk user.");

		Long zuID = AppticsIAMUtil.getCurrentUserZUID();
		if (zuID == null) 
		{
			ClientWriter.sendErrorResponse(response, AppticsConstants.UNAUTHORIZED, AppticsConstants.UNAUTHORIZED_MSG);
			return;
		}

		String[] split = state.split(",");
		if(!CommonUtil.isEmpty(error))
		{
			try 
			{
				response.sendRedirect("/ac/" + split[0] + "/" + split[1] + "/" + split[2] + "/settings#integrations/zendesk");
				return;
			} 
			catch (IOException e) 
			{
				LOGGER.log(Level.SEVERE, "user denied authentication", e);
			}
		}

		try 
		{
			boolean status = new ZenDeskHandler().authenticate(zuID, code, split[0], split[3]);

			LOGGER.log(Level.INFO, "Integration status : {0}", new Object[] { status });

			response.sendRedirect("/ac/" + split[0] + "/" + split[1] + "/" + split[2] + "/settings#integrations/zendesk");
		} 
		catch (Exception e)
		{
			LOGGER.log(Level.SEVERE, "Exception while authenciating zendesk user ", e);
		}

	}

	public void getOAuthTokens()
	{
		LOGGER.log(Level.INFO, "getting oauth Tokens for zendesk.");

		Long zuID = AppticsIAMUtil.getCurrentUserZUID();
		if(zuID == null )
		{
			ClientWriter.sendErrorResponse(response, AppticsConstants.UNAUTHORIZED, AppticsConstants.UNAUTHORIZED_MSG);
			return;
		}

		try 
		{

			JSONArray tokens = new ZenDeskHandler().getOAuthTokens(zuID);

			JSONObject result = new JSONObject();
			result.put("tokens", tokens);
			result.put("clientid", PropertyHandler.getValue(AppticsConstants.ZENDESKCLIENTID));

			ClientWriter.sendResponse(response, result);
		}
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while getting oauth tokens ", e);
			ClientWriter.sendErrorResponse(response, AppticsConstants.EXCEPTION, "Exception while getting oauth tokens, please try again later.");
		}
	}

	public void getConfiguration() 
	{
		LOGGER.log(Level.INFO, "get configuration.");

		Long zuID = AppticsIAMUtil.getCurrentUserZUID();
		if (zuID == null) 
		{
			ClientWriter.sendErrorResponse(response, AppticsConstants.UNAUTHORIZED, AppticsConstants.UNAUTHORIZED_MSG);
			return;
		}

		try 
		{
			JSONObject configuration = new ZenDeskHandler().getConfiguration(apid);

			ClientWriter.sendResponse(response, CommonUtil.isEmpty(configuration) ? new JSONObject() : configuration);
		} 
		catch (Exception e)
		{
			LOGGER.log(Level.SEVERE, "Exception while getting zendesk configuration ", e);
			ClientWriter.sendErrorResponse(response, AppticsConstants.EXCEPTION, "Exception while configuration, please try again later.");
		}
	}

	public void updateConfiguration() 
	{
		try 
		{

			LOGGER.log(Level.INFO, "Update zendesk configuration.");

			checkCurrentUserZUID();
			setCurrentUserRoles(projectID, zsoid);
			if (projectRole < 1) 
			{
				ClientWriter.sendErrorResponse(response, AppticsConstants.PERMISSION_DENIED, AppticsConstants.PERMISSION_DENIED_MSG);
				return;
			}

			isParamContainsEmpty(apid);
			isValiedAppPlatform(projectID, apid);

			JSONObject configuration = new JSONObject(request.getParameter(AppticsConstants.S_CONFIGURATION));

			configuration = new ZenDeskHandler().updateConfiguration(apid, configuration);

			ClientWriter.sendResponse(response, CommonUtil.isEmpty(configuration) ? new JSONObject() : configuration);

			Map<String,Object> param = ApplicationLog.getParameter(mode, "zendesk");
			ApplicationLog.addLog(ApplicationLog.INTEGRATIONS, null, projectID, request, param, 91, apid, "zendesk");
			User user = checkCurrentUser();
			String projectName = ProjectHandler.getDisplayName(projectID);
			String identifier =  AppHandler.getInstance().getIdentifierByAPID(apid);
			String portalName = ServiceOrgHandler.getInstance().getServiceOrgName(zsoid);

			List<Long> roleIDs = RoleHandler.getRoleIDs(RoleHandler.getRoleNameList(RoleHandler.MANAGERLEADANDDEVS), null);
			String email = ProjectSettingsHandler.getMemberEmailsAsCSV(projectID, roleIDs, false);

			String content = EmailNotificationContent.getIntegrationConfiguredMailContent("Zendesk", projectName, user.getDisplayName(), identifier, portalName);
			TransmailNotificationUtil.sendMail("Integration configurations updated", content, "no-reply@zohoapptics.com", email);

		} 
		catch (AppticsException e) 
		{
			LOGGER.log(Level.SEVERE, AppticsConstants.EXCEPTION, e);
			e.writeToClient(response);
		} 
		catch (Exception e)
		{
			LOGGER.log(Level.SEVERE, AppticsConstants.EXCEPTION, e);
			ClientWriter.sendErrorResponse(response, AppticsConstants.UNPROCESSABLE_ENTITY, AppticsConstants.UNPROCESSABLE_ENTITY_MSG, AppticsConstants.SC_EXPECTATION_FAILED);
		}

	}

	public void updateStatus()
	{
		try
		{
			LOGGER.log(Level.INFO, "update zendesk status.");

			setCurrentUserRoles(projectID, zsoid);
			if(projectRole < 1)
			{
				ClientWriter.sendErrorResponse(response, AppticsConstants.PERMISSION_DENIED, AppticsConstants.PERMISSION_DENIED_MSG);
				return;
			}
			isParamContainsEmpty(apid, status);
			isValiedAppPlatform(projectID, apid);

			new ZenDeskHandler().updateStatus(apid, status);

			ClientWriter.sendResponse(response, true);

			Map<String,Object> param = ApplicationLog.getParameter(mode, "zendesk");
			ApplicationLog.addLog(ApplicationLog.INTEGRATIONS, null, projectID, request, param,  92, status, apid, "zendesk");

			User user = checkCurrentUser();
			String projectName = ProjectHandler.getDisplayName(projectID);
			String identifier =  AppHandler.getInstance().getIdentifierByAPID(apid);
			String portalName = ServiceOrgHandler.getInstance().getServiceOrgName(zsoid);

			List<Long> roleIDs = RoleHandler.getRoleIDs(RoleHandler.getRoleNameList(RoleHandler.MANAGERLEADANDDEVS), null);
			String email = ProjectSettingsHandler.getMemberEmailsAsCSV(projectID, roleIDs, false);

			String content = EmailNotificationContent.getIntegrationEnabledOrDisabledMailContent(status, "Zendesk", projectName, user.getDisplayName(), identifier, portalName);
			String text = status ? "enabled" : "disabled";
			TransmailNotificationUtil.sendMail("Integration "+ text, content, "no-reply@zohoapptics.com", email);

		}
		catch (AppticsException e)
		{
			LOGGER.log(Level.SEVERE, AppticsConstants.EXCEPTION, e);
			e.writeToClient(response);
		}
		catch (Exception e)
		{
			LOGGER.log(Level.SEVERE, AppticsConstants.EXCEPTION, e);
			ClientWriter.sendErrorResponse(response, AppticsConstants.UNPROCESSABLE_ENTITY, AppticsConstants.UNPROCESSABLE_ENTITY_MSG, AppticsConstants.SC_EXPECTATION_FAILED);
		}
	}

	/* for UI pop-up  */


	public void getAgents()
