206		public JSONArray getOAuthTokens(long zuid) 
207		{
208			JSONArray tokens = new JSONArray();
209			try 
210			{
211				SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.REFRESHTOKEN));
212				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID));
213				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKEN));
214				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ACCESSTOKEN));
215				sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ADDEDTIME));
216	
217				Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), zuid, QueryConstants.EQUAL);
218				c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ZENDESK, QueryConstants.EQUAL, false));
219	
220				sq.setCriteria(c);
221	
222				DataObject dobj = DBHandler.getRedisCachePersistence().get(sq);
223	
224				if (!dobj.containsTable(AppticsConstants.REFRESHTOKEN)) 
225				{
226					LOGGER.log(Level.INFO, "No Rows found match with zuid = {0}", new Object[] { zuid });
227					return tokens;
228				}
229	
230				@SuppressWarnings("unchecked")
231				Iterator<Row> rows = dobj.getRows(AppticsConstants.REFRESHTOKEN);
232	
233				while (rows.hasNext()) 
234				{
235					Row row = rows.next();
236					JSONObject token = new JSONObject();
237					token.put("zendeskid", (Long) row.get(AppticsConstants.REFRESHTOKENID));
238					token.put("addedtime", (Long) row.get(AppticsConstants.ADDEDTIME));
239					token.put("subdomain", (String) row.get(AppticsConstants.ACCESSTOKEN));
240	
241					String accessToken = (String) row.get(AppticsConstants.REFRESHTOKEN);
242	
243					accessToken = accessToken.substring(0, 10) + "****" + accessToken.substring(accessToken.length() - 5, accessToken.length());
244	
245					token.put("accesstoken", accessToken);
246	
247					tokens.put(token);
248				}
249	
250				return tokens;
251			} 
252			catch (DataAccessException e) 
253			{
254				LOGGER.log(Level.SEVERE, "Exception while fetching current user zendesk OAuth Token", e);
255			}
256			return tokens;
257		}
