543		private String uploadFileForToken(String ticketID, File file, String accessToken, String subDomain) 
544		{
545			LOGGER.info("Generating token for attachment");
546			String uploadURL = ZENDESKURL.replace("$subdomain$", subDomain) + "/api/v2/uploads";
547			
548		
549	
550			JSONObject response = new JSONObject();
551			FileInputStream imageStream = null;
552			String token = null;
553			try 
554			{
555				
556			    CredentialsProvider credsProvider = new BasicCredentialsProvider();  //with proxy for serverType other than csez
557			     
558			    credsProvider.setCredentials(new AuthScope(AppticsConstants.PROXY_HOST, Integer.parseInt(AppticsConstants.PROXY_PORT)), 
559						new UsernamePasswordCredentials(AppticsConstants.PROXY_USER, AppticsConstants.PROXY_PASSWORD));
560			     
561			    
562				HttpHost proxy = new HttpHost(AppticsConstants.PROXY_HOST, Integer.parseInt(AppticsConstants.PROXY_PORT));
563	
564				HttpClientBuilder clientBuilder = HttpClientBuilder.create(); 
565			    clientBuilder.setProxy(proxy);
566			    clientBuilder.setDefaultCredentialsProvider(credsProvider);
567			    clientBuilder.setProxyAuthenticationStrategy(new ProxyAuthenticationStrategy());
568	
569				CloseableHttpClient httpclient = clientBuilder.build();
570				  
571				MultipartEntityBuilder multipartEntity = MultipartEntityBuilder.create();
572	
573				 HttpPost httppost = new HttpPost(new URIBuilder(uploadURL)
574				            .addParameter("filename", file.getName())
575				            .build());
576				httppost.addHeader("Authorization", "Bearer " + accessToken);
577				httppost.setHeader("Content-Type", "image/png");
578			
579	
580				imageStream = new FileInputStream(file);
581				InputStreamBody imageBody = new InputStreamBody(imageStream, ContentType.APPLICATION_OCTET_STREAM, file.getName());
582				multipartEntity.addPart("file", imageBody);
583	
584				httppost.setEntity(multipartEntity.build());
585	
586				CloseableHttpResponse res = httpclient.execute(httppost);
587	
588				int statusCode = res.getStatusLine().getStatusCode();
589				HttpEntity responseEntity = res.getEntity();
590				String responseString = EntityUtils.toString(responseEntity, "UTF-8");
591				if (statusCode == 201) 
592				{
593					JSONObject fullResponse = new JSONObject(responseString);
594					response = fullResponse.getJSONObject("upload");
595					token = response.has("token") ? response.getString("token") : "";
596					LOGGER.info("upload file response == > " + fullResponse);
597					return token;
598				}
599	
600			} 
601			catch (Exception e)
602			{
603				LOGGER.log(Level.SEVERE, "Exception while uploading upload token");
604			}
605			finally {
606				try 
607				{
608					if (imageStream != null)
609					{
610						imageStream.close();
611					}
612				} catch (IOException e) 
613				{
614					LOGGER.log(Level.SEVERE, "Exception while closing file object");
615				}
616			}
617			return token;
618	
619		}
