	public boolean authenticate(long zuID, String code, String loginName, String subDomain) 
	{
		String url = ZENDESKURL.replace("$subdomain$", subDomain) + "/oauth/tokens";

		String clientID = PropertyHandler.getValue(AppticsConstants.ZENDESKCLIENTID);
		String clientSecret = PropertyHandler.getValue(AppticsConstants.ZENDESKCLIENTSECRET);

		if (CommonUtil.isEmpty(clientID, clientSecret)) 
		{
			LOGGER.log(Level.INFO, "ZenDesk Client ID or Secret is empty");
			return false;
		}

		try 
		{

			Map<String, String> params = new HashMap<String, String>();

			params.put("grant_type", "authorization_code");
			params.put("code", code);
			params.put("client_id", clientID);
			params.put("client_secret", clientSecret);
			params.put("redirect_uri", AppticsConstants.SERVICEURL+"/api/zendesk/authenticate");
			params.put("scope", "read write");

			String res = new HttpURLConnectionInvoker(true).invokePostHttpURLConn(url, null, params);

			JSONObject response = new JSONObject(res);

			LOGGER.log(Level.INFO, response.toString());

			if (!response.has("access_token")) 
			{
				return false;
			}

			String accessToken = response.has("access_token") ? response.getString("access_token") : "";

			addZenDeskOAuth(zuID, accessToken, loginName, subDomain);

			return true;

		}
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while generating access token", e);
		}

		return false;
	}

	private Long addZenDeskOAuth(long zuID, String accessToken, String loginName, String subDomain) throws Exception 
	{
		Map<String, Object> ukcolumns = new HashMap<String, Object>();
		ukcolumns.put(AppticsConstants.ZUID, zuID);
		ukcolumns.put(AppticsConstants.REFRESHTOKEN, accessToken);
		ukcolumns.put(AppticsConstants.SERVICENAME, AppticsConstants.ZENDESK);
		ukcolumns.put(AppticsConstants.ACCESSTOKEN, subDomain); // using accesstoken column to store subdomain name

		if (MickeyUtil.isRowExist(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID, ukcolumns, loginName)) 
		{
			LOGGER.log(Level.INFO, "ZenDesk OAuth Details Already Exist. please Try different name.");
			throw new AppticsException(AppticsConstants.DUPLICATEENTRY, AppticsConstants.DUPLICATEENTRY);
		}

		Row row = new Row(AppticsConstants.REFRESHTOKEN);
		row.set(AppticsConstants.REFRESHTOKEN, accessToken);
		row.set(AppticsConstants.ZUID, zuID);
		row.set(AppticsConstants.SERVICENAME, AppticsConstants.ZENDESK);
		row.set(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());
		row.set(AppticsConstants.ACCESSTOKEN, subDomain);

		return DBHandler.insertRedisCacheRow(row, AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID, loginName);

	}

	public String getZendDeskOAuthToken(long zuID, long tokenID) throws DataAccessException
	{
		Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID), tokenID, QueryConstants.EQUAL);
		c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), zuID, QueryConstants.EQUAL));
		c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ZENDESK, QueryConstants.EQUAL, false));

		return (String) DBHandler.getColumnValueFromRedis(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID, c, AppticsConstants.REFRESHTOKEN);
	}

