	public JSONArray getOAuthTokens(long zuid) 
	{
		JSONArray tokens = new JSONArray();
		try 
		{
			SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.REFRESHTOKEN));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKEN));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ACCESSTOKEN));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ADDEDTIME));

			Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), zuid, QueryConstants.EQUAL);
			c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ZENDESK, QueryConstants.EQUAL, false));

			sq.setCriteria(c);

			DataObject dobj = DBHandler.getRedisCachePersistence().get(sq);

			if (!dobj.containsTable(AppticsConstants.REFRESHTOKEN)) 
			{
				LOGGER.log(Level.INFO, "No Rows found match with zuid = {0}", new Object[] { zuid });
				return tokens;
			}

			@SuppressWarnings("unchecked")
			Iterator<Row> rows = dobj.getRows(AppticsConstants.REFRESHTOKEN);

			while (rows.hasNext()) 
			{
				Row row = rows.next();
				JSONObject token = new JSONObject();
				token.put("zendeskid", (Long) row.get(AppticsConstants.REFRESHTOKENID));
				token.put("addedtime", (Long) row.get(AppticsConstants.ADDEDTIME));
				token.put("subdomain", (String) row.get(AppticsConstants.ACCESSTOKEN));

				String accessToken = (String) row.get(AppticsConstants.REFRESHTOKEN);

				accessToken = accessToken.substring(0, 10) + "****" + accessToken.substring(accessToken.length() - 5, accessToken.length());

				token.put("accesstoken", accessToken);

				tokens.put(token);
			}

			return tokens;
		} 
		catch (DataAccessException e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while fetching current user zendesk OAuth Token", e);
		}
		return tokens;
	}

	public Map<String, Object> createTicket(long projectID, long feedID) 
	{
		return createTicket(projectID, feedID, null);
	}

	public Map<String, Object> createTicket(long projectID, long feedID, Map<String, Object> feedInfo)
	{
		if (CommonUtil.isEmpty(feedInfo))
		{
			feedInfo = getFeedInfo(projectID, feedID);
		}

		String osVersion = feedInfo.containsKey(AppticsConstants.OSVERSION) ? (String)feedInfo.get(AppticsConstants.OSVERSION) : "";

		if(CommonUtil.isEmpty(osVersion))
		{
			try
			{
				Long osVersionID = DeskIntegration.getOSVersionIDByFeedID(feedID);
				feedInfo.put(AppticsConstants.OSVERSIONID, osVersionID);
				feedInfo.put(AppticsConstants.OSVERSION, OSVersionHandler.getInstance().getVersionNameByVersionID(osVersionID));
			}
			catch (DataAccessException e)
			{

				LOGGER.log(Level.SEVERE, "Exception getting os verion", e);
				feedInfo.put(AppticsConstants.OSVERSION, "");
			}
		}


		feedInfo.put("ZendeskWebURL", null);

		LOGGER.info("Feed info " + feedInfo.toString());

		String email = (String) feedInfo.get("MailID");
		long appID = (long) feedInfo.get("AppID");
		String report = (String) feedInfo.get("Report");
		int type = (int) feedInfo.get("Type");
		int mode = (int) feedInfo.get("Mode");
		long pid = (long) feedInfo.get("PID");
		long apID = (long) feedInfo.get("BundleID");
		String appversion = (String) feedInfo.get("AppVersion");
		long date = (long)feedInfo.get("Date");

		LOGGER.info("APID : " + apID);

		String moduleName = getModuleName(type);

		JSONObject moduleConf = IntegrationHandler.getIntegrationDetailsByService(AppticsConstants.ZENDESK, "feedback", moduleName, apID);

		if (CommonUtil.isEmpty(moduleConf))
		{
			LOGGER.log(Level.INFO, "Getting zendesk configuration as empty for {0}", new Object[] { apID });
			return feedInfo;
		}

		Long zenDeskID = moduleConf.getLong("zendeskid");

		if (CommonUtil.isEmpty(zenDeskID)) 
		{
			LOGGER.log(Level.INFO, "Getting zendesk id as empty for {0}", new Object[] { zenDeskID });
			return feedInfo;
		}

		Long zuID = moduleConf.getLong("zuid");

		String guestusername = "GuestUser";
		String projectDisplayname = "";
		try 
		{
			projectDisplayname = ProjectHandler.getDisplayName(appID);
		} 
		catch (DataAccessException e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while ", e);
		}

		report = CommonUtil.isEmpty(report) ? "new " + moduleName + " received" : report;

		guestusername = projectDisplayname + guestusername + "@apptics.com";
		email = CommonUtil.isValidEmail(email) ? email : guestusername;
		String name = email.split("@")[0];

		String timezone = AdminDBCache.getInstance().getTimeZone(appID);
		long startDateTimestamp = CalendarUtil.getStartTimeByLongDate(date, timezone);
    	long endDateTimestamp = CalendarUtil.getEndTimeByLongDate(date, timezone);
    	String startDate = CalendarUtil.formatDate("yyyy-MM-dd", startDateTimestamp, timezone);
    	String endDate = CalendarUtil.formatDate("yyyy-MM-dd", endDateTimestamp, timezone);
    	String zsoid = CommonUtil.getSASThreadLocalLoginName();
        String reporturl = AppticsConstants.SERVICEURL+"/ac/"+zsoid+"/"+appID+"/"+mode+"/tickets/11?sD="+startDate+"&eD="+endDate+"&feedID="+feedID;

		try 
		{

			String accessToken = getZendDeskOAuthToken(zuID, zenDeskID);
			String subDomain = moduleConf.getString("subdomain");

			LOGGER.info("Creating ticket in zendesk");
			String url = ZENDESKURL.replace("$subdomain$", subDomain) + "/api/v2/tickets";

			Map<String, String> headers = new HashMap<String, String>();
			headers.put("Authorization", "Bearer " + accessToken);
			headers.put("Content-Type" , "application/json");

			String modestr = mode == 1 ? "" : " - Development";
			String subject = moduleName + " - " + projectDisplayname + " " + appversion + " - " + AdminDBCache.getInstance().getOS(pid) + " " + feedInfo.get("OSVersion") + modestr;

			JSONObject requesterbody = new JSONObject();
			requesterbody.put("name", name);
			requesterbody.put("email", email);

			JSONObject comment = new JSONObject();

			comment.put("comment", report);
			comment.put("subject", subject);
			comment.put("requester", requesterbody);

			JSONObject ticket = new JSONObject();
			ticket.put("ticket", comment);

            JSONObject res = new HttpURLConnectionInvoker(true).invokeHttpURLConn(1, url, headers, ticket, null, true);
			JSONObject ticketObject = res.optJSONObject("ticket");

			if (ticketObject.has("id")) 
			{

				Integer ticketRes = ticketObject.getInt("id");
				String ticketID = ticketRes.toString();
				String webURL = ticketObject.getString("url");

				JSONObject integDetails = IntegrationHandler.getIntegrationDetails(feedID);

				Criteria c = new Criteria(Column.getColumn(AppticsConstants.BUGREPORTDETAILS, AppticsConstants.FEEDID), feedID, QueryConstants.EQUAL);

				JSONObject zendesk = new JSONObject();

				zendesk.put(AppticsConstants.TICKETID, ticketID);
				zendesk.put(SUBDOMAIN, subDomain);
				zendesk.put(AppticsConstants.WEBURL, webURL);
				zendesk.put(AppticsConstants.DATE, System.currentTimeMillis());
				zendesk.put(AppticsConstants.STATUSTEXT, ticketObject.getString("status"));
				zendesk.put(AppticsConstants.ORGID, zuID);
				zendesk.put(AppticsConstants.ASSIGNEEID, String.valueOf(ticketObject.optLong("assignee_id")));
				zendesk.put(AppticsConstants.PRIORITY, "");
				zendesk.put(AppticsConstants.CLASSIFICATION, "");
				zendesk.put(AppticsConstants.THREADS, "");
				zendesk.put(AppticsConstants.STATUS, "");
				zendesk.put("ZenDeskID", zenDeskID);

				integDetails.put("ZenDesk", zendesk);


				checkAndUploadAttachment(appID, ticketID, feedID, accessToken, subDomain);

				String ProjectIDs = PropertyHandler.getValue("DeskDefaultComment");
				if(!CommonUtil.isEmpty(ProjectIDs) && ProjectIDs.contains(appID+""))
				{
					String commentWithLink = AdminDBCache.getInstance().getOS(pid)+" - "+feedInfo.get(AppticsConstants.OSVERSION)+" - Appversion : "+appversion+" - "+feedInfo.get(AppticsConstants.MODEL)
					+" - "+"<a href='"+reporturl+"' target='_blank'>View in Apptics</a>";
					addCommentWithTicketID( ticketID, commentWithLink, accessToken, subDomain);
				}

				DBHandler.update(AppticsConstants.BUGREPORTDETAILS, c, AppticsConstants.INTEGRATIONDETAILS, integDetails.toString());

				feedInfo.put("ZendeskWebURL", webURL);
			}
		} 
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while creating zendesk ticket", e);
		}

		return feedInfo;
	}

	private void addCommentWithTicketID(String ticketID, String commentWithLink, String accessToken, String subDomain) 
	{

		LOGGER.info("Adding comment for the ticket");
		String url = ZENDESKURL.replace("$subdomain$", subDomain) + "/api/v2/tickets/" + ticketID;
		try 
		{
			Map<String, String> headers = new HashMap<String, String>();
			headers.put("Authorization", "Bearer " + accessToken);

			JSONObject comment = new JSONObject();
			comment.put("html_body", commentWithLink);
			comment.put("public", "false");

			JSONObject ticketBody = new JSONObject();
			ticketBody.put("comment", comment);

			JSONObject ticket = new JSONObject();
			ticket.put("ticket", ticketBody);

			JSONObject res = new HttpURLConnectionInvoker(true).invokeHttpURLConn(3, url, headers, ticket, null, false);
			LOGGER.info("Response : " + res);
		} 
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE, "exception while adding comment to the ticket");
		}


	}

	private void checkAndUploadAttachment(long appID, String ticketID, long feedID, String accessToken, String subDomain) 
	{
		LOGGER.info("Coming checkAndUploadAttachment for FeedID == " + feedID);
		SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.FEEDBACKATTACHMENT));
		sq.addSelectColumn(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.ATTACHMENTID));
		sq.addSelectColumn(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.FILEPATH));
		sq.addSelectColumn(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.BLOCKID));
		sq.setCriteria(new Criteria(Column.getColumn(AppticsConstants.FEEDBACKATTACHMENT, AppticsConstants.FEEDID), feedID, QueryConstants.EQUAL));

		DataObject dobj = null;
		File file = null;
		try 
		{
			dobj = DBHandler.getPersistence().get(sq);
			if (!dobj.containsTable(AppticsConstants.FEEDBACKATTACHMENT)) 
			{
				LOGGER.info("No Rows found match with feedid = " + feedID);
			} else 
			{
				@SuppressWarnings("unchecked")
				Iterator<Row> rows = dobj.getRows(AppticsConstants.FEEDBACKATTACHMENT);
				while (rows.hasNext()) {
					Row row = rows.next();
					String filePath = (String) row.get(AppticsConstants.FILEPATH);
					String blockID = (String) row.get(AppticsConstants.BLOCKID);
					LOGGER.info("filePath == > " + filePath + " blockID == > " + blockID);
					file = DFSFileHandler.dfsFileReadReturnFile(filePath, blockID, appID);
					String token = uploadFileForToken(ticketID, file, accessToken, subDomain);
					if (token != null)
					{
						uploadAttachment(ticketID, token, accessToken, subDomain);
					}
				}
			}
		} 
		catch (Exception e) 
		{
			LOGGER.log(Level.SEVERE, "Exception while getting token to add ZenDesk ticket", e);
		}
		finally 
		{
			CommonUtil.deleteTmpFileInAppServer(file);
		}
	}

