	private String uploadFileForToken(String ticketID, File file, String accessToken, String subDomain) 
	{
		LOGGER.info("Generating token for attachment");
		String uploadURL = ZENDESKURL.replace("$subdomain$", subDomain) + "/api/v2/uploads";



		JSONObject response = new JSONObject();
		FileInputStream imageStream = null;
		String token = null;
		try 
		{

		    CredentialsProvider credsProvider = new BasicCredentialsProvider();  //with proxy for serverType other than csez

		    credsProvider.setCredentials(new AuthScope(AppticsConstants.PROXY_HOST, Integer.parseInt(AppticsConstants.PROXY_PORT)), 
					new UsernamePasswordCredentials(AppticsConstants.PROXY_USER, AppticsConstants.PROXY_PASSWORD));


			HttpHost proxy = new HttpHost(AppticsConstants.PROXY_HOST, Integer.parseInt(AppticsConstants.PROXY_PORT));

			HttpClientBuilder clientBuilder = HttpClientBuilder.create(); 
		    clientBuilder.setProxy(proxy);
		    clientBuilder.setDefaultCredentialsProvider(credsProvider);
		    clientBuilder.setProxyAuthenticationStrategy(new ProxyAuthenticationStrategy());

			CloseableHttpClient httpclient = clientBuilder.build();

			MultipartEntityBuilder multipartEntity = MultipartEntityBuilder.create();

			 HttpPost httppost = new HttpPost(new URIBuilder(uploadURL)
			            .addParameter("filename", file.getName())
			            .build());
			httppost.addHeader("Authorization", "Bearer " + accessToken);
			httppost.setHeader("Content-Type", "image/png");


			imageStream = new FileInputStream(file);
			InputStreamBody imageBody = new InputStreamBody(imageStream, ContentType.APPLICATION_OCTET_STREAM, file.getName());
			multipartEntity.addPart("file", imageBody);

			httppost.setEntity(multipartEntity.build());

			CloseableHttpResponse res = httpclient.execute(httppost);

			int statusCode = res.getStatusLine().getStatusCode();
			HttpEntity responseEntity = res.getEntity();
			String responseString = EntityUtils.toString(responseEntity, "UTF-8");
			if (statusCode == 201) 
			{
				JSONObject fullResponse = new JSONObject(responseString);
				response = fullResponse.getJSONObject("upload");
				token = response.has("token") ? response.getString("token") : "";
				LOGGER.info("upload file response == > " + fullResponse);
				return token;
			}

		} 
		catch (Exception e)
		{
			LOGGER.log(Level.SEVERE, "Exception while uploading upload token");
		}
		finally {
			try 
			{
				if (imageStream != null)
				{
					imageStream.close();
				}
			} catch (IOException e) 
			{
				LOGGER.log(Level.SEVERE, "Exception while closing file object");
			}
		}
		return token;

	}

	public void checkTicketAndUploadAttachment(long appID, long attachmentID, long feedID) 
	{

		Map<String, Object> attachmentDetails = DBHandler.getCommonBean().getRowAsMap(SINGLEATTACHMENTDETAILS, AppticsConstants.ATTACHMENTID, attachmentID);

		 if(CommonUtil.isEmpty(attachmentDetails))
		 {
