	public JSONObject updateTicket(Long feedID, String updateKey, String updateValue) 
	{

		try 
		{
           JSONObject ticketDetail = IntegrationHandler.getIntegrationDetails(feedID);
           JSONObject integDetails = ticketDetail.getJSONObject(AppticsConstants.ZENDESK);

			String subDomain = integDetails.getString(SUBDOMAIN);
			String ticketID = integDetails.getString(AppticsConstants.TICKETID);
		    Long zendeskID = integDetails.getLong("ZenDeskID");
		    Long zuID = integDetails.getLong(AppticsConstants.ORGID);
			String accessToken = getZendDeskOAuthToken(zuID, zendeskID);

		    String url = ZENDESKURL.replace("$subdomain$", subDomain) + "/api/v2/tickets/"+ticketID;

			if(CommonUtil.isEmpty(accessToken))
			{
				LOGGER.log(Level.INFO, "Getting access token as empty.");
				throw new AppticsException(AppticsConstants.INVALID_OAUTH, AppticsConstants.INVALID_OAUTH_MSG);
			}

			Map<String, String> headers = new HashMap<String, String>();
			headers.put("Authorization", "Bearer " + accessToken);
			headers.put("Content-Type" , "application/json");

			JSONObject ticketBody = new JSONObject();
			if(updateKey.equals("assignee"))
			{
				ticketBody.put("assignee_id", updateValue);
			}
			else if(updateKey.equals("classification"))
			{
				ticketBody.put("type", updateValue);
			}
			else
			{
				ticketBody.put(updateKey, updateValue);
			}

			JSONObject params = new JSONObject();
			params.put("ticket", ticketBody);

			JSONObject response = new JSONObject();
//          JSONObject res = URLInvoker.invokePutURLWithJSONBodyWithProxy(url, params, headers, true);
            JSONObject res = new HttpURLConnectionInvoker(true).invokeHttpURLConn(3, url, headers, params, null, false);

			if(res.has("ticket"))
			{
				JSONObject ticketres = res.optJSONObject("ticket");

				String priority = ticketres.optString("priority");
				Long assigneeID = ticketres.optLong("assignee_id");
				String statusText = ticketres.optString("status");
				String classification = ticketres.optString("type");

				if(updateKey.equals("assignee"))
				{

					integDetails.put(AppticsConstants.ASSIGNEEID, assigneeID);
					integDetails.put(AppticsConstants.PRIORITY, priority);
					integDetails.put(AppticsConstants.STATUSTEXT, statusText);
					integDetails.put(AppticsConstants.CLASSIFICATION, classification);

					ticketDetail.put(AppticsConstants.ZENDESK, integDetails);

					Criteria c = new Criteria(Column.getColumn(AppticsConstants.BUGREPORTDETAILS, AppticsConstants.FEEDID), feedID, QueryConstants.EQUAL);

					DBHandler.update(AppticsConstants.BUGREPORTDETAILS, c, AppticsConstants.INTEGRATIONDETAILS, ticketDetail);

