				else
				{

					integDetails.put(AppticsConstants.PRIORITY, priority);
					integDetails.put(AppticsConstants.STATUSTEXT, statusText);
					integDetails.put(AppticsConstants.CLASSIFICATION, classification);

					ticketDetail.put(AppticsConstants.ZENDESK, integDetails);

					Criteria c = new Criteria(Column.getColumn(AppticsConstants.BUGREPORTDETAILS, AppticsConstants.FEEDID), feedID, QueryConstants.EQUAL);

					DBHandler.update(AppticsConstants.BUGREPORTDETAILS, c, AppticsConstants.INTEGRATIONDETAILS, ticketDetail);

				}
				response.put("response", "updated successfully");
				return response;
			}
			else
			{
				JSONObject error = res.optJSONObject("details");
				response.put("response", error);
				return response;
			}
		}
			catch(Exception e)
			{
				LOGGER.log(Level.SEVERE, "Exception while updating zendesk ticket ", e);
			}

		return null;
	}

        public Map<String, Object> createZenDeskTicket(String moduleName, String subType, long apid, String subject, String description, String email ) {

		LOGGER.log(Level.INFO, "creating ticket in zendesk");

		JSONObject zendeskDetails = IntegrationHandler.getIntegrationDetailsByService(AppticsConstants.ZENDESK, moduleName, subType, apid); //NO I18N

		if(CommonUtil.isEmpty(zendeskDetails))
		{
			return null;
		}
		try 
		{
			long zenDeskID = zendeskDetails.getLong("zendeskid"); //NO I18N
			long zuID = zendeskDetails.getLong("zuid"); //NO I18N
			String subDomain = zendeskDetails.getString("subdomain");
			String url = ZENDESKURL.replace("$subdomain$", subDomain) + "/api/v2/tickets"; //NO I18N
			String accessToken = new IntegrationHandler().getOAuthTokenByService(zuID, zenDeskID, AppticsConstants.ZENDESK);

			Map<String, String> headers = new HashMap<String, String>();
			headers.put("Authorization", "Bearer " + accessToken);
			headers.put("Content-Type" , "application/json");

			JSONObject requesterbody = new JSONObject();
			requesterbody.put("email", email);

			JSONObject comment = new JSONObject();
			comment.put("comment", description);
			comment.put("subject", subject);
			comment.put("requester", requesterbody);

			JSONObject ticket = new JSONObject();
			ticket.put("ticket", comment);

//			JSONObject res = URLInvoker.invokePostURLWithJSONBodyWithProxy(url, ticket, headers, true);
            JSONObject res = new HttpURLConnectionInvoker(true).invokeHttpURLConn(1, url, headers, ticket, null, false);

			JSONObject ticketObject = res.optJSONObject("ticket");

			if (ticketObject.has("id")) 
			{
				Map<String, Object> response = new HashMap<String, Object>();
			    response.put("response",response);
			    return response;
			}
		}
		catch (Exception e) 
		{
			LOGGER.log(Level.INFO, "Exception occured while createZenDeskTicket", e);
		}

		return null;
	}

	private String getModuleName(int type) 
	{
		if (type == 1) 
		{
			return AppticsConstants.FEEDBACK;
		}
		if (type == 0)
		{
			return AppticsConstants.BUG;
		}
		if (type == 2) 
		{
			return AppticsConstants.HELP;
		}
		return AppticsConstants.REPORT;
	}

	private Map<String, Object> getFeedInfo(Long projectID, Long feedID)
    {
		//TODO [santhosh]: ProjectWiseMigration - Usage = true and  Tested = CSEZ - true , Pre = false
		String appUserTable = AppticsConstants.APPUSERDETAILS+"_"+projectID;
		String query = "select b.DeviceConsent,d.ModelID,b.BundleID, b.PID,b.Mode,"
				+ "b.Type,b.Report,b.Language,b.TranslatedMessage,b.Sentiment,b.AppID,b.FileCheck,b.DFSFilePath,"
				+ "b.BlockID,b.Date,b.IntegrationDetails,ju.Encrypted_Email,ipv.Version AppVersion,b.OSVersion OSVersion, "
				+ "b.AppID, b.GuestEmail,ad.ModelID as AModelID,ad.DeviceID from BugReportDetails b LEFT JOIN "+appUserTable+" ju ON b.UserID=ju.UserID "
				+ "LEFT JOIN AppVersion ipv ON b.AppVersion=ipv.VersionID LEFT JOIN AppDeviceDetails_"+projectID+" d ON b.DeviceID=d.DeviceID "
				+ "LEFT JOIN AnonymousDeviceDetails_"+projectID+" ad ON b.DeviceID=ad.DeviceID where b.FeedID=?;";

		Map<String, Object> feedInfo = DBHandler.getCommonBean().getRowAsMap(query, AppticsConstants.FEEDID, feedID);

        Long pID = (Long) feedInfo.get(AppticsConstants.PID);

        String os = AdminDBCache.getInstance().getOS(pID);
		if(!CommonUtil.isEmpty(feedInfo.get(AppticsConstants.GUESTEMAIL)))
		{
			feedInfo.put(AppticsConstants.MAILID, new CipherTextDTTransformer().unTransform(AppticsConstants.BUGREPORTDETAILS, AppticsConstants.GUESTEMAIL, feedInfo.get(AppticsConstants.GUESTEMAIL), "SEARCHABLE_CTEXT"));
		}
		else if(AppticsConstants.ANDROID.equalsIgnoreCase(os) && !CommonUtil.isEmpty(feedInfo.get(AppticsConstants.ENCRYPTEDEMAIL)))
		{
			feedInfo.put(AppticsConstants.MAILID, new CipherTextDTTransformer().unTransform(appUserTable, AppticsConstants.ENCRYPTEDEMAIL, feedInfo.get(AppticsConstants.ENCRYPTEDEMAIL), "SEARCHABLE_CTEXT"));
		}
		else
		{
			feedInfo.put(AppticsConstants.MAILID, "");
		}
        String modelIDCoulmn = (Integer) feedInfo.get(AppticsConstants.DEVICECONSENT) == AppticsConstants.ANON_DEVICEID ? "AModelID" : AppticsConstants.MODELID;
        feedInfo.put(AppticsConstants.MODEL, DeviceHandler.getModelByID((Long)feedInfo.get(modelIDCoulmn)));

        return feedInfo;
    }


